package org.fruittwingpt.api;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.Instant; import java.util.*;
class ApiException extends RuntimeException { final HttpStatus status; ApiException(HttpStatus status,String message){super(message);this.status=status;} static ApiException notFound(String message){return new ApiException(HttpStatus.NOT_FOUND,message);} static ApiException conflict(String message){return new ApiException(HttpStatus.CONFLICT,message);} static ApiException unavailable(String message){return new ApiException(HttpStatus.SERVICE_UNAVAILABLE,message);} }
@RestControllerAdvice class ApiErrors { @ExceptionHandler(ApiException.class) ResponseEntity<Map<String,Object>> known(ApiException e){return ResponseEntity.status(e.status).body(Map.of("timestamp",Instant.now().toString(),"status",e.status.value(),"code",e.status.name(),"message",e.getMessage()));} @ExceptionHandler(org.springframework.web.bind.MethodArgumentNotValidException.class) ResponseEntity<Map<String,Object>> invalid(org.springframework.web.bind.MethodArgumentNotValidException e){var fields=new LinkedHashMap<String,String>();e.getBindingResult().getFieldErrors().forEach(f->fields.putIfAbsent(f.getField(),f.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("code","VALIDATION_ERROR","message",fields.values().stream().findFirst().orElse("Check the required fields"),"fields",fields));} }
